_CAL_MIN:154, Y_CAL_MAX:421,   // y range covered by the labelled data\n    // The 2026-08-22 sweep labels the whole physical range: the resting stop at\n    // y=447 (reads 0.09, so \"Under 0,3\") up to 5.7 at the top mark, y=154, fitted\n    // to within 0.06. The frame deliberately taken past the end of the scale sits\n    // at y=147, so this threshold splits 147 and 154 — above the printed scale,\n    // below anything the sweep put a number on.\n    Y_MAX_STATE:150,\n    /* The bottom state. Tested on FLOW, not on y, so it follows the curve — see\n       judge(). The ball rests at y=440.7 reading 0.20 with today's CAL. */\n    LOW_FLOW:0.3, LOW_LABEL:'Under 0,3',\n    LOW_REASON:\"Bollen ligger vid eller nära botten — flödet är under 0,3 L/min eller avstängt.\",\n    MAX_REASON:\"Bollen står vid eller ovanför det övre tjocka strecket — flödet är över skalans sista siffra.\",\n    /* What the device page SHOWS: x 215..440 of the oriented frame, the meter\n       alone. The LED sits left of the tube and blazes into the lens — mean\n       column brightness over the 2026-08-22 sweep peaks at 175 around x 175 and\n       falls off a cliff between x 210 (153) and x 220 (119) — so cropping there\n       drops the glare and roughly doubles the ball on her phone. Display only:\n       the analysis always gets the whole 480x640 frame. */\n    VIEW_X:215, VIEW_W:225, VIEW_Y:0, VIEW_H:640,\n    /* Lighting references in selection order; see the REF_PNG_* constants below\n       the table. A function because those constants are declared after it: they\n       are 400 kB of base64 and would bury every number above. */\n    refs:()=>[[REF_PNG,'natt'], [REF_PNG_DAY,'dag'], [REF_PNG_EVENING,'kväll']],\n  },\n  /* Invacare Platinum 9 (from 2026-09). 1-9 L/min with a red line at the top\n     of the scale; by its own front label the machine alarms below 1.0 and\n     loses O2 concentration above 9. Same principle as the EverFlo — a ball in\n     a tube, the knob on top — and the same cup fits.\n\n     Calibrated 2026-09-26 21:31-21:35 local against 21 labelled frames\n     (test/platinum9-sweep-2026-09-26), at night with the WS2812 AND the\n     kitchen's ceiling lamp on. Every number below was measured over that\n     sweep with the real engine; none was carried over from the EverFlo.\n     Margins: contrast 0.146 (gate 0.10), ambiguity 4.8x (3.0), registration\n     0.952 (0.75), spread 40 (75). Thinner than EverFlo's on every gate — the\n     tube is shorter in the picture, so 9 L/min fit in ~230 rows where EverFlo\n     spread 5.7 over ~290. */\n  platinum9:{\n    name:'Invacare Platinum 9',\n    /* The ball is a dark sphere with a bright specular highlight a few pixels\n       to its lower left, and the LED's reflection runs down the tube at x~300.\n       The band sits on the dark body and clear of both: centred on the\n       highlight (x 289..321, the first guess) the two cancel and contrast\n       fell to 0.03. Searched x-centre 304..324 and width 12..28, jointly with\n       the tilt: 312..324 is the best on both contrast and ambiguity. */\n    XL:312, XR:324,\n    /* The printed ticks left of the ball's path. The digits at the right\n       (x 330..364) register as well (0.955) but leave the thinnest ambiguity\n       at the red line; 264..292 gave the best resting-ball margin. */\n    AX1:264, AX2:292,\n    /* Two rivals, as on the EverFlo: the coupling at the top of the tube\n       (y~125) and the bottom fitting just under the resting ball (y~411-414).\n       The ball lives in y 171 (red line) .. 399 (resting stop). YTOP leaves\n       room for a ball pushed past the red line, and must stay under\n       Y_MAX_STATE; YBOT 405 clips the resting ball a little and evicts the\n       fitting (410+ lets it in: 1.2x at the red line). */\n    YTOP:138, YBOT:405,\n    RY1:80, RY2:470,\n    /* All 21 frames report zero tilt deviation at 0.03 and none refuses.\n       A line drawn along the tube by hand says 3.3 degrees (tan 0.058),